// Each message should be generated by the respective agent's prompt/persona.
export function getMockDebateMessages(topic: string): DebateMessage[] {
  return [
    {
      id: "1",
      agent: "a",
      name: "The YC Partner",
      message: `Look, "${topic}" is fundamentally a market question. What matters is TAM and velocity of adoption. If the developer ecosystem keeps shipping, the answer is obvious — follow the money.`,
      timestamp: new Date().toLocaleTimeString(),
    },
    {
      id: "2",
      agent: "b",
      name: "The Senior Engineer",
      message: `With respect, you're ignoring the technical debt curve. "${topic}" depends on whether the underlying architecture can sustain the next wave of requirements. Markets follow engineering constraints, not the other way around.`,
      timestamp: new Date(Date.now() + 2000).toLocaleTimeString(),
    },
    {
      id: "3",
      agent: "a",
      name: "The YC Partner",
      message: `Engineering constraints are solved with capital. Every single infra problem in history was solved by throwing enough smart people and money at it. The real question is: does anyone care enough to fund the solution?`,
      timestamp: new Date(Date.now() + 4000).toLocaleTimeString(),
    },
    {
      id: "4",
      agent: "b",
      name: "The Senior Engineer",
      message: `That's survivorship bias. For every funded solution, there are ten that burned through capital without shipping. Sustainable tech wins are built on sound abstractions, not pitch decks. The pragmatic answer lies somewhere in the middle.`,
      timestamp: new Date(Date.now() + 6000).toLocaleTimeString(),
    },
  ];
}

// TODO: Inject real LLM API call here
