export function getMockConclusion(topic: string): string {
  return `After rigorous debate on "${topic}", both agents converge on a key insight: sustainable progress requires both sound engineering foundations AND market validation. Neither capital alone nor pure technical elegance is sufficient — the winning strategy integrates pragmatic architecture with aggressive go-to-market execution. The debate revealed that the most resilient solutions emerge when builder conviction meets investor discipline.`;
}
